"""Load application config from a JSON file, falling back to built-in defaults."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

DEFAULT_CONFIG: dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "log_level": "INFO",
    "request_timeout_seconds": 30,
    "retries": 3,
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be used."""


def merge_with_defaults(overrides: dict[str, Any]) -> dict[str, Any]:
    unknown = set(overrides) - set(DEFAULT_CONFIG)
    if unknown:
        logger.warning("ignoring unknown config keys: %s", ", ".join(sorted(unknown)))
    merged = dict(DEFAULT_CONFIG)
    merged.update({key: value for key, value in overrides.items() if key in DEFAULT_CONFIG})
    return merged


def load_config(path: str | Path) -> dict[str, Any]:
    """Return the config at `path` merged over the defaults.

    A missing file is not an error; anything else wrong with it is.
    """
    path = Path(path)
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        logger.info("no config at %s, using defaults", path)
        return dict(DEFAULT_CONFIG)
    except OSError as exc:
        raise ConfigError(f"could not read config at {path}: {exc}") from exc

    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ConfigError(f"invalid JSON in {path}: {exc}") from exc

    if not isinstance(parsed, dict):
        raise ConfigError(f"expected a JSON object in {path}, got {type(parsed).__name__}")

    return merge_with_defaults(parsed)
